package com.citacloud.springboot.contacloud.app.models;
import jakarta.persistence.*;import java.math.BigDecimal;import java.util.UUID;
@Entity @Table(name="inventory_adjustment_line") public class LineaAjusteInventario{
 @Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;@Column(name="inventory_adjustment_id",nullable=false,updatable=false)private UUID ajusteId;@Column(name="tenant_id",nullable=false,updatable=false)private UUID tenantId;@Column(name="empresa_id",nullable=false,updatable=false)private UUID empresaId;@Column(name="product_id",nullable=false,updatable=false)private UUID productoId;@Column(name="unit_of_measure_id",nullable=false,updatable=false)private UUID unidadId;
 @Column(name="adjustment_quantity",nullable=false,updatable=false,precision=19,scale=4)private BigDecimal cantidadAjuste;@Column(name="base_quantity",nullable=false,updatable=false,precision=19,scale=4)private BigDecimal cantidadBase;@Column(name="conversion_factor",nullable=false,updatable=false,precision=19,scale=8)private BigDecimal factorConversion;@Column(name="balance_before",precision=19,scale=4)private BigDecimal saldoAnterior;@Column(name="balance_after",precision=19,scale=4)private BigDecimal saldoPosterior;
 @Column(name="product_code_snapshot",nullable=false,updatable=false,length=24)private String codigoProducto;@Column(name="product_name_snapshot",nullable=false,updatable=false,length=300)private String nombreProducto;@Column(name="unit_snapshot",nullable=false,updatable=false,length=120)private String unidad;@Column(name="line_order",nullable=false,updatable=false)private int orden;
 protected LineaAjusteInventario(){} public LineaAjusteInventario(AjusteInventario a,Producto p,BigDecimal q,int orden){ajusteId=a.getId();tenantId=a.getTenantId();empresaId=a.getEmpresaId();productoId=p.getId();unidadId=p.getUnidadMedidaId();cantidadAjuste=q;cantidadBase=q;factorConversion=BigDecimal.ONE;codigoProducto=p.getCodigo();nombreProducto=p.getNombre();unidad=p.getUnidadMedida()==null?"Unidad":p.getUnidadMedida().getNombre();this.orden=orden;}
 public void capturarSaldos(BigDecimal antes,BigDecimal despues){if(saldoAnterior!=null||saldoPosterior!=null)throw new IllegalStateException("Los saldos históricos ya fueron registrados.");saldoAnterior=antes;saldoPosterior=despues;}
 public UUID getId(){return id;}public UUID getAjusteId(){return ajusteId;}public UUID getProductoId(){return productoId;}public UUID getUnidadId(){return unidadId;}public BigDecimal getCantidadAjuste(){return cantidadAjuste;}public BigDecimal getCantidadBase(){return cantidadBase;}public BigDecimal getFactorConversion(){return factorConversion;}public BigDecimal getSaldoAnterior(){return saldoAnterior;}public BigDecimal getSaldoPosterior(){return saldoPosterior;}public String getCodigoProducto(){return codigoProducto;}public String getNombreProducto(){return nombreProducto;}public String getUnidad(){return unidad;}public int getOrden(){return orden;}
}
